CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS departments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, email text NOT NULL UNIQUE, role text NOT NULL, department_id uuid REFERENCES departments(id), mfa_enrolled boolean NOT NULL DEFAULT false, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS access_scopes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), department_id uuid REFERENCES departments(id), empreendimento_id uuid, classification text, purpose text NOT NULL, granted_by uuid REFERENCES users(id), expires_at timestamptz);
CREATE TABLE IF NOT EXISTS budgets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), department_id uuid NOT NULL REFERENCES departments(id), competence date NOT NULL, version integer NOT NULL DEFAULT 1, status text NOT NULL DEFAULT 'rascunho', budgeted numeric(18,2) NOT NULL DEFAULT 0, planned numeric(18,2) NOT NULL DEFAULT 0, committed numeric(18,2) NOT NULL DEFAULT 0, realized numeric(18,2) NOT NULL DEFAULT 0, forecast numeric(18,2) NOT NULL DEFAULT 0, source text NOT NULL, checksum text NOT NULL, UNIQUE(department_id, competence, version));
CREATE TABLE IF NOT EXISTS agenda_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, department_id uuid REFERENCES departments(id), owner_id uuid REFERENCES users(id), starts_at timestamptz NOT NULL, priority text NOT NULL, status text NOT NULL, classification text NOT NULL, source text NOT NULL, archived_at timestamptz);
CREATE TABLE IF NOT EXISTS committees (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL, audience text NOT NULL, competence date NOT NULL, status text NOT NULL, classification text NOT NULL, topics jsonb NOT NULL DEFAULT '[]', created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid REFERENCES users(id), action text NOT NULL, entity text NOT NULL, entity_id text NOT NULL, reason text NOT NULL, before_state jsonb, after_state jsonb, evidence jsonb, correlation_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS compliance_reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), requirement text NOT NULL, rule_version text NOT NULL, result text NOT NULL, evidence jsonb NOT NULL DEFAULT '[]', human_owner text NOT NULL, caveats text, exceptions text, treatment_plan text, approver text, due_at date, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS record_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity text NOT NULL, entity_id uuid NOT NULL, version integer NOT NULL, state jsonb NOT NULL, changed_by uuid REFERENCES users(id), reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(entity, entity_id, version));
CREATE TABLE IF NOT EXISTS budget_import_batches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), checksum text NOT NULL UNIQUE, source text NOT NULL, rows_total integer NOT NULL, rows_valid integer NOT NULL, rows_invalid integer NOT NULL, imported_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS integration_contracts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source text NOT NULL, entity_type text NOT NULL, external_id text, payload jsonb NOT NULL, source_timestamp timestamptz, sync_status text NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(source, entity_type, external_id));
